function MatrixBackground() {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return undefined;
    const ctx = canvas.getContext("2d");
    if (!ctx) return undefined;

    let frame = 0;
    let columns = [];
    let width = window.innerWidth;
    let height = window.innerHeight;
    const fontSize = 15;

    const resize = () => {
      width = window.innerWidth;
      height = window.innerHeight;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.floor(width * dpr);
      canvas.height = Math.floor(height * dpr);
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      columns = Array.from({ length: Math.ceil(width / fontSize) }, () => ({
        y: Math.random() * height,
        speed: 0.25 + Math.random() * 0.9,
        length: 8 + Math.floor(Math.random() * 22),
        opacity: 0.12 + Math.random() * 0.4,
      }));
    };

    const draw = () => {
      ctx.fillStyle = "rgba(8,0,7,0.13)";
      ctx.fillRect(0, 0, width, height);
      ctx.font = `${fontSize}px "JetBrains Mono", monospace`;
      ctx.textBaseline = "top";

      columns.forEach((column, index) => {
        const x = index * fontSize;

        for (let j = 0; j < column.length; j += 1) {
          const y = column.y - j * fontSize;
          if (y < -fontSize || y > height) continue;

          const progress = 1 - j / column.length;
          const char = MATRIX_CHARS[Math.floor(Math.random() * MATRIX_CHARS.length)];

          if (j === 0) {
            ctx.fillStyle = `rgba(255,240,252,${0.95 * progress})`;
            ctx.shadowBlur = 15;
            ctx.shadowColor = "rgba(255,40,180,0.9)";
          } else {
            ctx.fillStyle = `rgba(255,20,160,${column.opacity * progress})`;
            ctx.shadowBlur = 5;
            ctx.shadowColor = "rgba(255,0,150,0.5)";
          }

          ctx.fillText(char, x, y);
        }

        ctx.shadowBlur = 0;
        column.y += column.speed * 2;

        if (column.y - column.length * fontSize > height) {
          column.y = -Math.random() * 500;
        }
      });

      frame = requestAnimationFrame(draw);
    };

    resize();
    draw();
    window.addEventListener("resize", resize);

    return () => {
      cancelAnimationFrame(frame);
      window.removeEventListener("resize", resize);
    };
  }, []);

  return <canvas ref={canvasRef} className="matrix-canvas" aria-hidden="true" />;
}

function Sparkles({ count = 100 }) {
  const items = useMemo(
    () =>
      Array.from({ length: count }, (_, id) => ({
        id,
        left: Math.random() * 100,
        top: Math.random() * 100,
        size: 1 + Math.random() * 4,
        delay: Math.random() * 6,
        duration: 2 + Math.random() * 5,
      })),
    [count]
  );

  return (
    <div className="sparkles" aria-hidden="true">
      {items.map((item) => (
        <span
          key={item.id}
          className="sparkle"
          style={{
            left: `${item.left}%`,
            top: `${item.top}%`,
            width: `${item.size}px`,
            height: `${item.size}px`,
            animationDelay: `${item.delay}s`,
            animationDuration: `${item.duration}s`,
          }}
        />
      ))}
    </div>
  );
}

function Hearts({ count = 24 }) {
  const items = useMemo(
    () =>
      Array.from({ length: count }, (_, id) => ({
        id,
        left: Math.random() * 100,
        delay: Math.random() * 8,
        duration: 6 + Math.random() * 7,
        size: 10 + Math.random() * 15,
        type: Math.random() > 0.5 ? "♥" : "♡",
      })),
    [count]
  );

  return (
    <div className="hearts" aria-hidden="true">
      {items.map((item) => (
        <span
          key={item.id}
          className="floating-heart"
          style={{
            left: `${item.left}%`,
            animationDelay: `${item.delay}s`,
            animationDuration: `${item.duration}s`,
            fontSize: `${item.size}px`,
          }}
        >
          {item.type}
        </span>
      ))}
    </div>
  );
}

function BootTerminal({ onComplete }) {
  const [started, setStarted] = useState(false);
  const [lineIndex, setLineIndex] = useState(0);
  const [text, setText] = useState("");
  const [exiting, setExiting] = useState(false);

  useEffect(() => {
    if (!started) return undefined;

    if (lineIndex >= bootLines.length) {
      setExiting(true);
      const timer = setTimeout(onComplete, 1500);
      return () => clearTimeout(timer);
    }

    const line = bootLines[lineIndex];

    if (line === "") {
      setText("");
      const timer = setTimeout(() => setLineIndex((value) => value + 1), 650);
      return () => clearTimeout(timer);
    }

    setText("");
    let index = 0;

    const typing = setInterval(() => {
      index += 1;
      setText(line.slice(0, index));

      if (index >= line.length) {
        clearInterval(typing);
        setTimeout(() => setLineIndex((value) => value + 1), 900);
      }
    }, 55);

    return () => clearInterval(typing);
  }, [started, lineIndex, onComplete]);

  if (!started) {
    return (
      <section className="launch-screen">
        <MatrixBackground />
        <Sparkles count={120} />
        <Hearts count={28} />
        <div className="launch-glow" />

        <div className="launch-panel">
          <div className="launch-top">
            <span className="live-dot" />
            Защищённое подключение
            <span>v28.08.26</span>
          </div>

          <div className="launch-content">
            <div className="launch-symbol">♥</div>
            <div className="launch-small">
              День-рожденьский 
              <br />
              поздравительный протокол
            </div>

            <h1>
              Если готова увидеть мои старания
              <span>Жми на розовую кнопку</span>
            </h1>

            <p>
              Не думай жми!
            </p>


<button
  className="launch-button"
  type="button"
  onClick={() => {
    const audio = new Audio(BACKGROUND_MUSIC);
    audio.loop = true;
    audio.volume = 0.35;

    audio.play().catch((error) => {
      console.warn("Music playback blocked:", error);
    });

    setStarted(true);
  }}
>
  <span>&gt; Жми Жми!</span>
  <b>→</b>
</button>



            <div className="launch-hint">Жми на кнопку!</div>
          </div>
        </div>
      </section>
    );
  }

  return (
    <section className={`terminal-screen ${exiting ? "terminal-exit" : ""}`}>
      <MatrixBackground />
      <Sparkles count={120} />
      <Hearts count={28} />
      <div className="pink-vignette" />
      <div className="terminal-grid" />

      <div className="terminal-small-window">
        <div className="terminal-bar">
          <div className="window-controls">
            <span />
            <span />
            <span />
          </div>
          <span className="terminal-title">BIRTHDAY_PROTOCOL.exe</span>
          <span className="terminal-version">SECURE</span>
        </div>

        <div className="terminal-status-bar">
          <span className="terminal-status" />
          CONNECTION:
          <b>ENCRYPTED</b>
          <span className="status-line" />
          <span>256-BIT</span>
        </div>

        <div className="terminal-line">
          <span className="prompt">&gt;</span>
          <span className="terminal-text">{text}</span>
          <span className="terminal-cursor">_</span>
        </div>

        <div className="terminal-footer">
          <span>● SYSTEM ONLINE</span>
          <span>DO NOT CLOSE</span>
        </div>
      </div>
    </section>
  );
}

function HackerScreen({ onComplete }) {
  const [lineIndex, setLineIndex] = useState(0);
  const [text, setText] = useState("");
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    if (lineIndex >= hackLines.length) {
      const timer = setTimeout(onComplete, 1800);
      return () => clearTimeout(timer);
    }

    const line = hackLines[lineIndex];

    if (line === "") {
      setText("");
      const timer = setTimeout(() => setLineIndex((value) => value + 1), 700);
      return () => clearTimeout(timer);
    }

    let index = 0;
    setText("");

    const typing = setInterval(() => {
      index += 1;
      setText(line.slice(0, index));
      setProgress(
        Math.min(
          100,
          Math.round(
            ((lineIndex + index / Math.max(line.length, 1)) / hackLines.length) * 100
          )
        )
      );

      if (index >= line.length) {
        clearInterval(typing);
        setTimeout(() => setLineIndex((value) => value + 1), 700);
      }
    }, 48);

    return () => clearInterval(typing);
  }, [lineIndex, onComplete]);

  return (
    <section className="hacker-screen">
      <MatrixBackground />
      <Sparkles count={130} />
      <Hearts count={36} />

      <div className="hacker-glow glow-a" />
      <div className="hacker-glow glow-b" />

      <div className="hacker-panel">
        <div className="hacker-header">
          <div>
            <span className="pink-dot" />
            PRIVATE_CHANNEL
          </div>
          <span>[ ENCRYPTED ]</span>
        </div>

        <div className="hacker-body">
          <div className="hack-logo">
            <span>♥</span>
            <div>
              <small>SYSTEM</small>
              <strong>Темка поздравительная</strong>
            </div>
          </div>

          <div className="hack-terminal">
            <div className="hack-line">
              <span className="hack-prompt">root@heart:~$</span>
              <span>{text}</span>
              <i />
            </div>
          </div>

          <div className="progress-info">
            <span>DECRYPTING</span>
            <b>{progress}%</b>
          </div>

          <div className="progress-track">
            <div className="progress-fill" style={{ width: `${progress}%` }} />
          </div>

          <div className="hack-cards">
            <div><span>STATUS</span><b>ONLINE</b></div>
            <div><span>Temka-Link</span><b>♥ CONNECTED</b></div>
            <div><span>SECURITY</span><b>BYPASSED</b></div>
          </div>
        </div>

        <div className="hacker-footer">
          <span>SYSTEM_TIME://NOW</span>
          <span>BIRTHDAY_PROTOCOL_ACTIVE</span>
        </div>
      </div>
    </section>
  );
}

function PhotoTarget({ name, photo }) {
  return (
    <div className="target-box">
      <div className="target-header">
        <span>TARGET</span>
        <span>VERIFIED ♥</span>
      </div>

      <div className="target-content">
        <div className={`avatar-core ${photo ? "has-photo" : ""}`}>
          {photo ? <img src={photo} alt="" /> : <span>♥</span>}
        </div>

        <div className="target-identity">
          <small>IDENTITY</small>
          <strong>{name}</strong>
          <span>SPECIAL_PERSON</span>
        </div>

        <div className="target-status">
          <i />
          ONLINE
        </div>
      </div>
    </div>
  );
}

function GeneratedNeonField() {
  const items = useMemo(
    () =>
      Array.from({ length: 360 }, (_, id) => ({
        id,
        left: Math.random() * 100,
        top: Math.random() * 100,
        size: 2 + Math.random() * 10,
        delay: Math.random() * 8,
        duration: 2 + Math.random() * 7,
        rotation: Math.random() * 360,
        symbol: ["✦", "✧", "♥", "♡", "◆", "◇"][id % 6],
      })),
    []
  );

  return (
    <div className="generated-neon-field" aria-hidden="true">
      {items.map((item) => (
        <span
          key={item.id}
          className="generated-neon-item"
          style={{
            left: `${item.left}%`,
            top: `${item.top}%`,
            fontSize: `${item.size}px`,
            animationDelay: `${item.delay}s`,
            animationDuration: `${item.duration}s`,
            transform: `rotate(${item.rotation}deg)`,
          }}
        >
          {item.symbol}
        </span>
      ))}
    </div>
  );
}

function BirthdayExperience() {
  const [openedWish, setOpenedWish] = useState(null);
  const [showFinal, setShowFinal] = useState(false);
  const [pulse, setPulse] = useState(false);

  const triggerFinal = () => {
    setPulse(true);
    setTimeout(() => {
      setShowFinal(true);
      setPulse(false);
    }, 650);
  };

  return (
    <section className={`experience ${pulse ? "screen-pulse" : ""}`}>
      <div className="experience-bg" />
      <div className="pink-orb orb-one" />
      <div className="pink-orb orb-two" />
      <div className="pink-orb orb-three" />
      <div className="experience-grid" />
      <GeneratedNeonField />
      <ProfileSignalField />
      <Sparkles count={180} />
      <Hearts count={50} />

      <main className="message-interface">
        <div className="interface-header">
          <div className="brand"><span>♥</span>PRIVATE_MESSAGE</div>
          <div className="connection"><i />SECURE</div>
        </div>

        <div className="message-body">
          <div className="system-label">[ MESSAGE_RECEIVED ]</div>
          <div className="scan-line" />

          <h1>
            CONNECTION
            <span>ESTABLISHED</span>
          </h1>

          <p className="message-subtitle">
            Система успешно нашла адресата.
            <br />
            И теперь у неё есть кое-что важное.
          </p>

          <PhotoTarget name={TARGET_NAME} photo={TARGET_PHOTO} />

          <div className="message-text">
            <p>Система успешно подгрузила все данные</p>
            <p>
              И вывела всё в лучшем виде
            </p>
            <p className="pink-text">С днём рождения.</p>
            <p>
              Я желаю тебе счастья, здоровья
            </p>
            <p>Пусть всё, что ты хочешь, постепенно становится реальностью.</p>
          </div>

          <div className="wish-grid">
            {wishes.map((wish, index) => (
              <button
                key={wish.title}
                type="button"
                className={`wish-card ${openedWish === index ? "active" : ""}`}
                onClick={() => setOpenedWish(openedWish === index ? null : index)}
              >
                <div className="wish-top">
                  <span className="wish-icon">{wish.icon}</span>
                  <span className="wish-index">0{index + 1}</span>
                </div>
                <strong>{wish.title}</strong>
                <span className="wish-arrow">{openedWish === index ? "−" : "+"}</span>
                {openedWish === index && (
                  <div className="wish-description">{wish.text}</div>
                )}
              </button>
            ))}
          </div>

          {!showFinal ? (
            <button type="button" className="execute-button" onClick={triggerFinal}>
              <span>&gt; EXECUTE_SECRET_MESSAGE</span>
              <b>♥</b>
            </button>
          ) : (
            <div className="final-message">
              <div className="final-glow" />
              <div className="final-symbol">♥</div>
              <span className="final-label">[ SECRET_MESSAGE.exe ]</span>

              <div className="final-divider">
                <span />
                <i>✦</i>
                <span />
              </div>

              <h2>
                С ДНЁМ
                <span>РОЖДЕНИЯ!</span>
              </h2>

              <p>Самое главное — просто будь счастлива.</p>
              <p>
                Пусть этот новый год твоей жизни принесёт тебе именно то,
                чего тебе хочется больше всего.
              </p>

              <strong>
                Сделано с
                <br />
                душой ♥
              </strong>

              <div className="final-hearts">♥　♡　♥　♡　♥</div>
            </div>
          )}
        </div>

        <div className="interface-footer">
          <span>LOVE_PROTOCOL v2.0</span>
          <span>STATUS: <b>COMPLETED</b></span>
        </div>
      </main>
    </section>
  );
}

export default function App() {
  const [stage, setStage] = useState("boot");

  const handleBootComplete = () => setStage("hack");
  const handleHackComplete = () => setStage("experience");

  return (
    <div className="app">
      {stage === "boot" && <BootTerminal onComplete={handleBootComplete} />}
      {stage === "hack" && <HackerScreen onComplete={handleHackComplete} />}
      {stage === "experience" && <BirthdayExperience />}
    </div>
  );
}

