function ProfileSignalField() {
  return (
    <div className="profile-signal-field" aria-hidden="true">
      {NEON_PROFILES.map((profile) => (
        <span
          key={profile.id}
          className="profile-signal"
          data-zone={profile.zone}
          style={{
            opacity: profile.intensity,
            transform: `scale(${profile.scale})`,
            animationDelay: `${profile.delay}s`,
            animationDuration: `${profile.drift + 4}s`,
          }}
        >
          {profile.glyph}
        </span>
      ))}
    </div>
  );
}

